import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';

/**
 * Hardcoded admin credentials.
 *
 * There is no backend admin-login endpoint yet, so this is a client-side-only
 * gate for the /admin area (matches what the seed/demo data in the rest of
 * the admin module already does). It stops casual/accidental access, but it
 * is NOT real security — anyone with devtools can read these constants or
 * flip the localStorage flag below. Swap this out for a real POST /admin/login
 * call once that endpoint exists.
 */
const ADMIN_USERNAME = 'admin';
const ADMIN_PASSWORD = 'admin123';

const ADMIN_ROLE = 'ADMIN';

export const adminGuard: CanActivateFn = () => {
  const router = inject(Router);

  const alreadyAuthenticated =
    localStorage.getItem('role') === ADMIN_ROLE && !!localStorage.getItem('token');

  if (alreadyAuthenticated) {
    return true;
  }

  const username = window.prompt('Admin login\n\nUsername:');
  if (username === null) {
    // Cancelled the prompt.
    router.navigate(['/']);
    return false;
  }

  const password = window.prompt('Admin login\n\nPassword:');
  if (password === null) {
    router.navigate(['/']);
    return false;
  }

  if (username === ADMIN_USERNAME && password === ADMIN_PASSWORD) {
    localStorage.setItem('token', 'admin-local-session');
    localStorage.setItem('role', ADMIN_ROLE);
    localStorage.setItem('id', '0');
    localStorage.setItem('adminUsername', username);
    return true;
  }

  alert('Invalid admin username or password.');
  router.navigate(['/']);
  return false;
};
